import type { JSX } from 'preact';
import sizes from './titleImage.json';

// The site title is a picture of the Nabla colour font rather than text in it: Safari can't draw that font (it gets a
// black stand-in) and every browser has to fetch it before the title shows. These are the title drawn at 4x its
// displayed size, trimmed to the letters, as /public/title-<size>.avif and .webp. Sized in em, so they follow the
// font-size of whatever holds them (see .titleImage). The pictures and titleImage.json (their sizes) are generated by
// scripts/gen-title.cjs.
export function TitleImage(props: { text: string; size: 'hero' | 'brand' }): JSX.Element {
  const { width, height, em } = sizes[props.size];
  return (
    <picture>
      <source srcset={`/title-${props.size}.avif`} type="image/avif" />
      <source srcset={`/title-${props.size}.webp`} type="image/webp" />
      <img
        class="titleImage"
        src={`/title-${props.size}.webp`}
        alt={props.text}
        width={width}
        height={height}
        style={{ '--title-em': em }}
        // the hero is the first thing on the page, so it decodes with the rest instead of arriving a beat later
        decoding={props.size === 'hero' ? 'auto' : 'async'}
        fetchpriority={props.size === 'hero' ? 'high' : undefined}
      />
    </picture>
  );
}
